{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 맞는 개선 방법을 정한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리에서 응답 지연이 발생한 상황.",
          "task": "확인한 병목에 적합한 쿼리 개선 방법을 정하는 일.",
          "action": "실행 계획과 조회 구조에서 확인한 병목을 바탕으로 개선 방법의 선택 기준을 설명한다.",
          "result": "개선 전후 응답 시간과 측정 조건은 꼬리질문에서 확인."
        },
        "expectedEvidence": [
          "쿼리 개선 방법을 정한 기준이 실행 계획이나 조회 구조에서 확인한 병목과 연결된다.",
          "선택한 개선 방법이 해당 병목을 줄이는 데 적합하다고 본 이유가 드러난다."
        ]
      },
      "question": "운영 화면의 신고 목록 조회 쿼리를 개선하셨다고 했는데요. 어떤 기준으로 쿼리 개선 방법을 정하셨나요?",
      "answerTip": "당시 경험을 떠올리며 본인이 판단한 내용을 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획이나 조회 구조에서 실제로 확인한 병목을 구체적으로 제시하며 개선 방법의 선택 기준을 설명한다.",
            "선택한 방법이 해당 병목을 줄이는 데 적합한 이유를 쿼리의 특성과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "쿼리 개선 방법의 선택 기준은 제시하지만, 실제로 확인한 병목에 대한 설명이 부족하다.",
            "선택한 방법의 일반적인 장점은 설명하지만 해당 조회 쿼리에 적합한 이유는 약하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스 추가나 쿼리 수정 등 수행한 작업만 나열하고 선택 기준을 설명하지 못한다.",
            "선택한 개선 방법을 병목과 연결하지 못하거나 응답 시간이 줄었다는 결과만 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류의 원인을 좁힐 때 사용한 로그상의 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 알림 중복 발송 오류가 발생한 상황.",
          "task": "오류를 추적해 중복 발송의 원인을 좁히는 일.",
          "action": "로그에서 확인한 사실을 근거로 가능한 원인을 구분하고 원인 판단의 이유를 설명한다.",
          "result": "복구 조치와 재발 방지 방안의 구분 및 적용 결과는 꼬리질문에서 확인."
        },
        "expectedEvidence": [
          "알림 중복 발송 오류의 원인을 좁힌 근거로 실제 로그에서 확인한 사실을 제시한다.",
          "로그에서 확인한 사실이 특정 원인을 뒷받침한다고 판단한 이유가 드러난다."
        ]
      },
      "question": "배포 후 알림 중복 발송 오류를 로그로 추적하셨다고 했는데요. 무엇을 근거로 알림 중복 발송 오류의 원인을 좁히셨나요?",
      "answerTip": "기억나는 한 장면을 중심으로 본인이 겪은 일을 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 실행 시점이나 실행 주체 등 실제 관찰 사실을 원인 판단의 근거로 구체적으로 제시한다.",
            "관찰한 사실이 알림 중복 발송의 특정 원인을 뒷받침하는 이유를 논리적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그를 근거로 원인을 좁혔다고 설명하지만 실제로 확인한 내용이 구체적이지 않다.",
            "관찰 사실과 판단한 원인을 제시하지만 둘 사이의 연결에 대한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "원인의 명칭만 말하거나 추측을 제시하고 로그에서 확인한 근거를 설명하지 못한다.",
            "복구 작업이나 재발 방지 조치만 설명하고 원인을 좁힌 근거는 제시하지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "개발·디자인 담당자와 구현 범위를 합의할 수 있도록 요청을 요구사항 정의서로 구체화한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성했던 상황.",
          "task": "요청의 목적을 바탕으로 구현 범위와 우선순위, 예외 케이스를 명확히 정의하는 과제.",
          "action": "요청을 구체적인 요구사항으로 작성할 때 적용한 기준을 실제 문서 내용에 연결해 설명한다.",
          "result": "정의한 범위에 대한 개발 담당자와의 합의 여부는 꼬리질문에서 확인."
        },
        "expectedEvidence": [
          "요구사항의 구체화 기준이 요청의 목적과 연결되어 있다.",
          "포함·제외 범위와 우선순위를 문서에 명시하는 기준이 실제 요구사항을 통해 드러난다.",
          "예외 케이스를 요구사항으로 명확히 정의하는 기준이 드러난다."
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨네요. 어떤 기준으로 개발 담당자가 구현할 요구사항을 구체화하셨나요?",
      "answerTip": "당시 작성했던 내용 중 한 가지를 떠올려 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요청의 목적을 실제 요구사항과 연결해 구체화 기준을 설명한다.",
            "포함·제외 범위와 우선순위를 명시한 기준을 실제 문서 내용으로 설명한다.",
            "예외 케이스를 명확히 정의한 기준을 설명해 구현 범위의 모호함을 줄였음을 보여준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항을 구체화한 기준은 설명하지만 요청의 목적과의 연결이 약하다.",
            "범위, 우선순위, 예외 케이스 중 일부의 작성 기준만 드러나거나 실제 문서 내용에 대한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요청을 정리했다는 설명에 그치고 요구사항을 구체화한 기준을 제시하지 못한다.",
            "문서 양식이나 도구 사용만 설명해 구현 범위를 정의한 판단을 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "개발자와 디자이너가 구현 내용을 명확히 이해할 수 있도록 화면설계서의 설계 내용을 구체화한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "Figma로 화면설계서 28장을 작성했던 상황.",
          "task": "기능 흐름과 화면별 상태 변화, 예외 상황, 안내 문구를 구현 가능한 수준으로 작성하는 과제.",
          "action": "화면별 설계 내용을 어느 수준까지 명시할지 정한 기준을 실제 화면 사례에 연결해 설명한다.",
          "result": "화면설계서에 대한 구현 담당자의 추가 확인 필요 여부는 꼬리질문에서 확인."
        },
        "expectedEvidence": [
          "설계 내용의 구체화 기준이 구현 담당자의 해석 여지를 줄이는 데 연결되어 있다.",
          "기능 흐름과 화면별 상태 변화를 명시하는 기준이 실제 화면 사례에서 드러난다.",
          "예외 상황과 그에 필요한 안내 문구를 명시하는 기준이 드러난다."
        ]
      },
      "question": "Figma로 화면설계서 28장을 작성하셨다고 했는데요. 화면 구현에 필요한 설계 내용을 어떤 기준으로 구체화하셨나요?",
      "answerTip": "직접 작성했던 화면 하나를 떠올려 답변을 풀어가 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 담당자의 해석 여지를 줄이기 위한 설계 내용의 구체화 기준을 실제 화면 사례로 설명한다.",
            "기능 흐름과 화면별 상태 변화를 어느 수준까지 명시했는지 그 기준을 설명한다.",
            "예외 상황과 안내 문구를 설계서에 명시한 기준을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "설계 내용을 구체화한 기준은 제시하지만 구현 담당자의 이해와 연결한 설명이 약하다.",
            "기능 흐름, 상태 변화, 예외 상황, 안내 문구 중 일부의 작성 기준만 드러나거나 실제 화면 사례가 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면을 그렸다는 설명에 그치고 설계 내용을 구체화한 기준을 제시하지 못한다.",
            "도구 조작이나 시각적 배치만 설명해 기능 흐름과 화면 상태를 구현 가능한 수준으로 정의했는지 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방의 이상 여부와 투약 전 확인 필요성을 근거로 투약 중단을 판단할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "진통제 처방 용량이 평소 용량의 두 배로 들어왔던 상황",
          "task": "처방의 적절성이 확인되지 않은 상태에서 투약을 진행해도 되는지 판단해야 했음",
          "action": "기존 용량과의 차이와 처방의 적절성이 확인되지 않았다는 점을 근거로 투약 중단이 필요하다고 판단함",
          "result": "담당자 확인 이후의 경과는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "투약을 멈춰야 한다고 판단한 근거로 기존 용량과 해당 처방 용량의 구체적인 차이를 제시한다.",
          "용량 차이만으로 처방 오류를 확정하지 않고, 적절성이 확인되지 않은 처방을 그대로 수행할 수 없다는 점을 설명한다."
        ]
      },
      "question": "진통제 처방 용량이 평소 용량의 두 배로 들어온 적이 있다고 하셨는데요. 당시 투약을 멈춰야 한다고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 떠올리며 본인의 생각을 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "기존 용량과 처방 용량의 차이를 구체적으로 제시하며 투약 중단 판단의 근거로 연결한다.",
            "용량 차이를 확인이 필요한 신호로 해석하고, 처방의 적절성이 확인되지 않은 상태에서는 투약을 진행할 수 없다고 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "용량이 평소와 달라 확인이 필요했다는 판단 근거는 제시하지만, 비교한 내용이나 투약 중단과의 연결이 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단 근거 없이 담당의에게 확인했다는 행동이나 입력 오류였다는 결과만 설명한다.",
            "처방의 차이나 확인 필요성과 관계없는 이유만 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 변화를 정확히 남기기 위해 간호 기록 내용을 정하는 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "활력징후와 통증을 관찰하며 환자 상태 변화를 기록했던 한 사례",
          "task": "관찰된 상태 변화가 정확히 드러나도록 간호 기록 내용을 정해야 했음",
          "action": "실제 관찰·측정 사실과 이전 상태 대비 변화를 기준으로 기록 내용을 정함",
          "result": "기록 이후 보고와 인수인계로 이어진 내용은 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "기록 내용을 정한 기준으로 실제 관찰하거나 측정한 환자 상태를 제시한다.",
          "관찰 시점과 이전 상태 대비 변화가 드러나야 한다는 기준을 해당 사례와 연결해 설명한다."
        ]
      },
      "question": "활력징후와 통증 관찰 기록을 맡으셨다고 했는데요. 한 사례를 골라, 환자 상태 변화의 기록 내용을 어떤 기준으로 정하셨나요?",
      "answerTip": "여러 경험을 나열하기보다 한 장면에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "선택한 사례에서 실제로 관찰하거나 측정한 사실을 바탕으로 기록 내용을 정한 기준을 설명한다.",
            "관찰 시점과 이전 상태 대비 변화가 드러나도록 기록 내용을 정했다는 기준을 사례 속 사실과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "관찰 사실이나 상태 변화를 기록한다는 기준은 제시하지만, 해당 사례에서 어떤 내용을 중요하게 보았는지 불분명하다."
          ]
        },
        "poor": {
